#ifndef __ST7789_HSPI_H
#define __ST7789_HSPI_H

#include "stm32f4xx_hal.h"
#include "spi.h"   // hspi1 generated by CubeMX

/* Control pins: plain GPIO, same wiring as the software-SPI version */
#define ST7789_CS_PIN    GPIO_PIN_0
#define ST7789_CS_PORT   GPIOA

#define ST7789_DC_PIN    GPIO_PIN_1
#define ST7789_DC_PORT   GPIOA

#define ST7789_RST_PIN   GPIO_PIN_2
#define ST7789_RST_PORT  GPIOA

/* Data pins (handled by hardware SPI1 peripheral, NOT by GPIO):
 *   PA5  -> SPI1_SCK
 *   PA7  -> SPI1_MOSI
 *   PA6  -> SPI1_MISO (not connected to LCD, keep floating)
 */
#define ST7789_HSPI_HANDLE    hspi1

/* LCD resolution 240*240 */
#define ST7789_W  240
#define ST7789_H  240

/* Row offset of the 240x240 window inside the 240x320 controller RAM.
 * Different panels use 0 / 40 / 80. If a black bar appears at the TOP,
 * the offset is too big -> decrease it. If at the BOTTOM -> increase it. */
#define ST7789_X_OFFSET  0
#define ST7789_Y_OFFSET  0

/* Colors RGB565 */
#define WHITE   0xFFFF
#define BLACK   0x0000
#define RED     0xF800
#define GREEN   0x07E0
#define BLUE    0x001F
#define YELLOW  0xFFE0
#define CYAN    0x07FF
#define MAGENTA 0xF81F
#define GRAY    0x8410

/* Same API as st7789_softspi, upper-layer code needs no change */
void ST7789_SPI_SendByte(uint8_t dat);
void ST7789_WriteCmd(uint8_t cmd);
void ST7789_WriteData(uint8_t data);
void ST7789_WriteData16(uint16_t data);
void ST7789_Reset(void);
void ST7789_Init(void);
void ST7789_SetWindow(uint16_t x0, uint16_t y0, uint16_t x1, uint16_t y1);
void ST7789_Clear(uint16_t color);
void ST7789_DrawPoint(uint16_t x, uint16_t y, uint16_t color);
void ST7789_DrawRect(uint16_t x0, uint16_t y0, uint16_t x1, uint16_t y1, uint16_t color);
void ST7789_DrawFillRect(uint16_t x0, uint16_t y0, uint16_t x1, uint16_t y1, uint16_t color);
void ST7789_DrawFillCircle(int16_t x0, int16_t y0, int16_t r, uint16_t color);
void ST7789_ShowImage2x(const uint8_t *src, uint16_t w, uint16_t h);
/* bpp: 2 = RGB565 big-endian, 1 = RGB332 (expanded on the fly) */
void ST7789_ShowImageScale(const uint8_t *src, uint16_t w, uint16_t h, uint8_t scale, uint8_t bpp);
void ST7789_ShowImageAuto(const uint8_t *src, uint16_t w, uint16_t h, uint8_t bpp);
void ST7789_MoveFillCircle(int16_t xOld, int16_t yOld, int16_t xNew, int16_t yNew,
                           int16_t r, uint16_t fgColor, uint16_t bgColor);

#endif